CREATE UNIQUE INDEX uniq_groups_name_folded_active ON groups (name_folded) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uniq_users_username_folded_active ON users (username_folded) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uniq_users_email_folded_active ON users (email_folded) WHERE deleted_at IS NULL AND email <> '';
CREATE UNIQUE INDEX uniq_users_external_id_active ON users (external_id) WHERE deleted_at IS NULL AND external_id != '';
CREATE UNIQUE INDEX uniq_projects_name_active ON projects (LOWER(name)) WHERE deleted_at IS NULL AND name <> '';
CREATE UNIQUE INDEX uniq_roles_name_folded ON roles (name_folded);
CREATE UNIQUE INDEX uniq_share_records_active ON share_records (secret_id, recipient_id, is_group) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uniq_secret_versions_node_version ON secret_versions (secret_node_id, version_number);
